import Foundation

@frozen public struct LocalizedStringKey: Equatable, ExpressibleByStringInterpolation {
    @usableFromInline var key: String
    @usableFromInline var hasFormatting: Bool = false
    @usableFromInline var arguments: [FormatArgument]
    @usableFromInline struct FormatArgument: Equatable { var value: String }
    public init(_ value: String) { key = value; arguments = [] }
    public init(stringLiteral value: String) { self.init(value) }
    public init(stringInterpolation: StringInterpolation) {
        key = stringInterpolation.value
        arguments = []
    }
    public struct StringInterpolation: StringInterpolationProtocol {
        var value: String
        public init(literalCapacity: Int, interpolationCount: Int) {
            value = ""
            value.reserveCapacity(literalCapacity)
        }
        public mutating func appendLiteral(_ literal: String) { value += literal }
        public mutating func appendInterpolation(_ string: String) { value += string }
    }
}
extension Text {
    public init(_ key: LocalizedStringKey, tableName: String? = nil,
                bundle: Bundle? = nil, comment: StaticString? = nil) {
        // Resolve the resource table through Foundation; untranslated keys use
        // the key itself, just as localizedString(forKey:) does.
        let text = (bundle ?? .main).localizedString(forKey: key.key, value: nil, table: tableName)
        self.init(verbatim: text)
    }
}
public struct ButtonRole: Equatable {
    private let value: UInt8
    public static let destructive = Self(value: 0)
    public static let cancel = Self(value: 1)
}
public struct Button<Label: View>: View {
    private let label: Label
    private let action: () -> Void
    private let role: ButtonRole?
    public init(action: @escaping () -> Void, @ViewBuilder label: () -> Label) {
        self.action = action
        self.label = label()
        role = nil
    }
    public init(role: ButtonRole?, action: @escaping () -> Void, @ViewBuilder label: () -> Label) {
        self.role = role
        self.action = action
        self.label = label()
    }
    public var body: some View { label }
    public static func _makeView(view: _GraphValue<Self>, inputs: _ViewInputs) -> _ViewOutputs {
        var labelInputs = inputs
        if labelInputs.foreground.isEmpty { labelInputs.foreground = [Color.blue.resolve(inputs)] }
        if view.value.role == .destructive { labelInputs.foreground = [Color.red.resolve(inputs)] }
        let label = Label._makeView(view: _GraphValue(value: view.value.label), inputs: labelInputs.child("label"))
        return makeButton(label: label, action: view.value.action, inputs: inputs)
    }
}
extension Button where Label == Text {
    public init(_ titleKey: LocalizedStringKey, action: @escaping () -> Void) {
        self.init(action: action) { Text(titleKey) }
    }
    @_disfavoredOverload public init<S: StringProtocol>(_ title: S, action: @escaping () -> Void) {
        self.init(action: action) { Text(verbatim: String(title)) }
    }
    public init(_ titleKey: LocalizedStringKey, role: ButtonRole?, action: @escaping () -> Void) {
        self.init(role: role, action: action) { Text(titleKey) }
    }
}
private struct AlertView<Content: View, Actions: View, Message: View>: View {
    let content: Content
    let title: LocalizedStringKey
    let isPresented: Binding<Bool>
    let actions: Actions
    let message: Message
    typealias Body = Never
    static func _makeView(view: _GraphValue<Self>, inputs: _ViewInputs) -> _ViewOutputs {
        precondition(!view.value.isPresented.wrappedValue,
                     "SwiftUI: presenting an alert requires interactive presentation support")
        return Content._makeView(view: _GraphValue(value: view.value.content), inputs: inputs)
    }
}
private struct PresentingAlertView<Content: View, Actions: View, Message: View, Data>: View {
    let content: Content
    let title: Text
    let isPresented: Binding<Bool>
    let data: Data?
    let actions: Actions?
    let message: Message?
    typealias Body = Never
    static func _makeView(view: _GraphValue<Self>, inputs: _ViewInputs) -> _ViewOutputs {
        precondition(!view.value.isPresented.wrappedValue || view.value.data == nil,
                     "SwiftUI: presenting an alert requires interactive presentation support")
        return Content._makeView(view: _GraphValue(value: view.value.content), inputs: inputs)
    }
}
extension View {
    public func alert<A: View, M: View>(_ titleKey: LocalizedStringKey, isPresented: Binding<Bool>,
                                      @ViewBuilder actions: () -> A, @ViewBuilder message: () -> M) -> some View {
        AlertView(content: self, title: titleKey, isPresented: isPresented, actions: actions(), message: message())
    }
    public func onOpenURL(perform action: @escaping (URL) -> Void) -> some View {
        OpenURLView(content: self, action: action)
    }
    public func alert<A: View, M: View, T>(_ titleKey: LocalizedStringKey, isPresented: Binding<Bool>,
        presenting data: T?, @ViewBuilder actions: (T) -> A, @ViewBuilder message: (T) -> M) -> some View {
        PresentingAlertView(content: self, title: Text(titleKey), isPresented: isPresented,
                            data: data, actions: data.map(actions), message: data.map(message))
    }
    @_disfavoredOverload public func alert<S: StringProtocol, A: View, M: View, T>(_ title: S, isPresented: Binding<Bool>,
        presenting data: T?, @ViewBuilder actions: (T) -> A, @ViewBuilder message: (T) -> M) -> some View {
        PresentingAlertView(content: self, title: Text(verbatim: String(title)), isPresented: isPresented,
                            data: data, actions: data.map(actions), message: data.map(message))
    }
    public func alert<A: View, M: View, T>(_ title: Text, isPresented: Binding<Bool>,
        presenting data: T?, @ViewBuilder actions: (T) -> A, @ViewBuilder message: (T) -> M) -> some View {
        PresentingAlertView(content: self, title: title, isPresented: isPresented,
                            data: data, actions: data.map(actions), message: data.map(message))
    }
}

private var openURLHandlers: [(URL) -> Void] = []
func clearOpenURLHandlers() { openURLHandlers.removeAll() }
private struct OpenURLView<Content: View>: View {
    let content: Content
    let action: (URL) -> Void
    typealias Body = Never
    static func _makeView(view: _GraphValue<Self>, inputs: _ViewInputs) -> _ViewOutputs {
        let objects = inputs.objects
        let action = view.value.action
        openURLHandlers.append { url in EnvironmentScope.withObjects(objects) { action(url) } }
        return Content._makeView(view: _GraphValue(value: view.value.content), inputs: inputs)
    }
}
// Backend event entry point. This is also used by the independent SDK fixture
// to verify that evaluating the view does not invoke the action prematurely.
@_cdecl("iosandroid_swiftui_open_url")
public func _dispatchOpenURL(_ string: UnsafePointer<CChar>) -> Bool {
    guard let url = URL(string: String(cString: string)) else { return false }
    let snapshot = openURLHandlers
    for action in snapshot { action(url) }
    return !snapshot.isEmpty
}
// An action read outside a presented destination has nothing to dismiss.
public struct DismissAction {
    let action: (() -> Void)?
    fileprivate init(action: (() -> Void)? = nil) { self.action = action }
    public func callAsFunction() { action?() }
}
private struct DismissKey: EnvironmentKey { static let defaultValue = DismissAction() }
extension EnvironmentValues {
    public var dismiss: DismissAction { self[DismissKey.self] }
    public var isPresented: Bool { self[DismissKey.self].action != nil }
    var _presentationDismiss: DismissAction {
        get { self[DismissKey.self] }
        set { self[DismissKey.self] = newValue }
    }
}

// Sheets and full-screen covers: while presented, the content is laid over the presenter, filling
// it, on the system background; dismiss and presentationMode inside it end the presentation.
struct _PresentedLayer<Base: View, Presented: View>: View {
    let base: Base
    let isPresented: Binding<Bool>
    let onDismiss: (() -> Void)?
    let presented: () -> Presented
    var body: some View {
        ZStack {
            base
            if isPresented.wrappedValue {
                presented()
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(Color(uiColor: .systemBackground))
                    .environment(\._presentationDismiss, DismissAction(action: {
                        isPresented.wrappedValue = false
                        onDismiss?()
                    }))
            }
        }
    }
}

private func _itemPresented<Item>(_ item: Binding<Item?>) -> Binding<Bool> {
    Binding(get: { item.wrappedValue != nil }, set: { if !$0 { item.wrappedValue = nil } })
}

extension View {
    public func sheet<Item, Content>(item: Binding<Item?>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping (Item) -> Content) -> some View where Item: Identifiable, Content: View {
        _PresentedLayer(base: self, isPresented: _itemPresented(item), onDismiss: onDismiss) { content(item.wrappedValue!) }
    }
    public func sheet<Content>(isPresented: Binding<Bool>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping () -> Content) -> some View where Content: View {
        _PresentedLayer(base: self, isPresented: isPresented, onDismiss: onDismiss, presented: content)
    }
    public func fullScreenCover<Item, Content>(item: Binding<Item?>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping (Item) -> Content) -> some View where Item: Identifiable, Content: View {
        _PresentedLayer(base: self, isPresented: _itemPresented(item), onDismiss: onDismiss) { content(item.wrappedValue!) }
    }
    public func fullScreenCover<Content>(isPresented: Binding<Bool>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping () -> Content) -> some View where Content: View {
        _PresentedLayer(base: self, isPresented: isPresented, onDismiss: onDismiss, presented: content)
    }
}

